#include "FooterBar.h"
FooterBar::FooterBar(ScratchPadAudioProcessor& p):processor(p){setMouseCursor(juce::MouseCursor::PointingHandCursor);}
void FooterBar::paint(juce::Graphics& g){auto r=getLocalBounds().toFloat();juce::Path banner;banner.startNewSubPath(0,4);banner.lineTo(r.getWidth()*.47f,4);banner.lineTo(r.getWidth()*.51f,r.getHeight()*.48f);banner.lineTo(r.getWidth()*.47f,r.getBottom()-3);banner.lineTo(0,r.getBottom()-3);banner.closeSubPath();g.setColour(juce::Colour::fromRGB(23,25,29));g.fillPath(banner);g.setColour(Theme::cyan.withAlpha(.5f));g.strokePath(banner,juce::PathStrokeType(1.f));g.setFont(Theme::font(24,true));g.setColour(Theme::cyan);g.drawFittedText("SCRATCHPAD",13,5,(int)(r.getWidth()*.43f),28,juce::Justification::centredLeft,1);int x=(int)(r.getWidth()*.54f);g.setFont(Theme::font(15,true));g.drawText("Menu",x,3,54,16,juce::Justification::centredLeft);g.drawText("Rename",x,20,60,16,juce::Justification::centredLeft);g.drawText(juce::String::fromUTF8("\xE2\x97\x82"),x+67,17,15,20,juce::Justification::centred);g.setColour(Theme::light);g.drawFittedText(processor.presetName,x+85,17,getWidth()-x-104,20,juce::Justification::centred,1);g.setColour(Theme::cyan);g.drawText(juce::String::fromUTF8("\xE2\x96\xB8"),getWidth()-19,17,16,20,juce::Justification::centred);}
void FooterBar::mouseUp(const juce::MouseEvent& e){int x=(int)(getWidth()*.54f);if(e.x<x)return;if(e.x<x+63){if(e.y<18)menu();else rename();return;}if(e.x<x+85){preset=(preset+2)%3;if(loadPreset)loadPreset(preset);}else if(e.x>getWidth()-24){preset=(preset+1)%3;if(loadPreset)loadPreset(preset);}repaint();}
void FooterBar::rename(){juce::Component::SafePointer<FooterBar> safe(this);auto* window=new juce::AlertWindow("Rename preset","Enter new preset name",juce::MessageBoxIconType::NoIcon);window->addTextEditor("name",processor.presetName);window->addButton("OK",1);window->addButton("Cancel",0);window->enterModalState(true,juce::ModalCallbackFunction::create([safe,window](int result){if(safe&&result==1){safe->processor.presetName=window->getTextEditorContents("name");safe->repaint();}delete window;}),false);}
void FooterBar::menu(){juce::PopupMenu m;m.addItem(1,"Save preset...");m.addItem(2,"Load preset...");m.addItem(3,"Init");m.addItem(4,"About ScratchPad");juce::Component::SafePointer<FooterBar> safe(this);m.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(this),[safe](int i){if(!safe)return;if(i==3){safe->processor.setCurve({{0,1,0},{1,0,0}});safe->processor.presetName="Init";safe->repaint();}if(i==4)juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::InfoIcon,"ScratchPad","Original scratch-envelope effect by Skell Audio.");if(i==1||i==2){auto chooser=std::make_shared<juce::FileChooser>(i==1?"Save ScratchPad preset":"Load ScratchPad preset",juce::File{},"*.scratchpad");auto flags=i==1?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles:juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles;chooser->launchAsync(flags,[safe,chooser,i](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File{})return;if(i==1){juce::MemoryBlock mb;safe->processor.getStateInformation(mb);file.replaceWithData(mb.getData(),mb.getSize());}else{juce::MemoryBlock mb;if(file.loadFileAsData(mb))safe->processor.setStateInformation(mb.getData(),(int)mb.getSize());}safe->repaint();});}});}
